const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const bryceCanyon = ee.Geometry.Point([-112.1826, 37.5930]); // Bryce Canyon NP
  const lasVegas = ee.Geometry.Point([-115.1398, 36.1699]); // Las Vegas

  const startDate = '2024-01-01';
  const endDate = '2024-12-31';

  // 2. Data Acquisition & Check
  const nightlights = ee.ImageCollection('VIIRS/DNB/MONTHLY_V1/VCMSLCFG')
    .filterDate(startDate, endDate)
    .select('avg_rad');

  const bryceCol = nightlights.filterBounds(bryceCanyon);
  const vegasCol = nightlights.filterBounds(lasVegas);

  const bryceSize = bryceCol.size().getInfo();
  const vegasSize = vegasCol.size().getInfo();

  console.log(`Bryce Canyon images: ${bryceSize}`);
  console.log(`Las Vegas images: ${vegasSize}`);

  if (bryceSize === 0 || vegasSize === 0) {
    console.log("Missing data for one or both locations.");
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Calculate mean nighttime light intensity
  const bryceMean = bryceCol.mean();
  const vegasMean = vegasCol.mean();

  // 4. Calculate statistics
  const bryceStats = bryceMean.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: bryceCanyon.buffer(5000),
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const vegasStats = vegasMean.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: lasVegas.buffer(5000),
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const bryceValue = bryceStats['avg_rad_mean'];
  const bryceCount = bryceStats['avg_rad_count'];
  const vegasValue = vegasStats['avg_rad_mean'];
  const vegasCount = vegasStats['avg_rad_count'];

  console.log(`Bryce Canyon: Mean=${bryceValue}, Pixels=${bryceCount}`);
  console.log(`Las Vegas: Mean=${vegasValue}, Pixels=${vegasCount}`);

  // 5. Validation & Final Answer
  if (bryceCount === 0 || vegasCount === 0) {
    console.log("No valid pixels after processing.");
    console.log("<answer>C2</answer>");
    return;
  }

  if (bryceValue === null || bryceValue === undefined || 
      vegasValue === null || vegasValue === undefined ||
      isNaN(bryceValue) || isNaN(vegasValue)) {
    console.log("Calculation failure - invalid results.");
    console.log("<answer>C3</answer>");
    return;
  }

  console.log(`Bryce/Vegas ratio: ${(bryceValue/vegasValue).toFixed(4)}`);

  if (bryceValue < vegasValue) {
    console.log("Bryce Canyon is darker than Las Vegas.");
    console.log("<answer>A</answer>");
  } else {
    console.log("Bryce Canyon is not darker than Las Vegas.");
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
